/**
 * Inserts the token unless the user already holds `maxUsable` usable ones in
 * the org (not revoked, not yet expired at `createdAt`). Count and insert run
 * in one synchronous transaction so concurrent creations cannot both slip
 * under the limit. Resolves `null` when the limit is reached.
 */
export async function insertApiTokenWithinLimit(
  input: NewApiToken,
