sed -i 's/, randomToken, hasRoleAtLeast$/, randomToken/' src/server/services/api-token-service.ts && sed -n 3,5p src/server/services/api-token-service.ts
mkdir -p tests/tmp && cat > tests/tmp/smoke.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it } from "vitest";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as svc from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import { listActivity } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

it("works", async () => {
  const t = await createTenant("smoke");
  const inp = { orgId: t.org.id, name: " ci ", scope: "write" as const, expiresInDays: 1 };
  await expect(svc.createApiToken(t.actors.viewer, inp)).rejects.toThrow(/Permission/);
  const { token, apiToken } = await svc.createApiToken(t.actors.member, inp);
  expect(token.startsWith("tfk_")).toBe(true);
  expect(apiToken.prefix).toBe(token.slice(0, 12));
  expect(apiToken.name).toBe("ci");
  expect(await svc.authenticateApiToken(token)).toEqual({ userId: t.userIds.member, orgId: t.org.id, role: "member" });
  expect((await svc.listApiTokens(t.actors.member, t.org.id))[0]!.lastUsedAt).not.toBeNull();
  for (let i = 0; i < 4; i++) await svc.createApiToken(t.actors.member, { ...inp, scope: "read" });
  await expect(svc.createApiToken(t.actors.member, inp)).rejects.toThrow();
  const list = await svc.listApiTokens(t.actors.member, t.org.id);
  expect(list.length).toBe(5);
  expect(list[0]!.id).not.toBe(apiToken.id);
  await expect(svc.listApiTokens(t.actors.member, t.org.id, t.userIds.admin)).rejects.toThrow(/Permission/);
  await svc.revokeApiToken(t.actors.admin, t.org.id, list[1]!.id);
  const again = await svc.revokeApiToken(t.actors.admin, t.org.id, list[1]!.id);
  expect(again.revokedAt).not.toBeNull();
  const member = (await import("@/server/repositories/member-repository")).findMember;
  const m = await member(t.org.id, t.userIds.member);
  await memberService.removeMember(t.actors.admin, { orgId: t.org.id, memberId: m!.id } as never);
  expect(await svc.authenticateApiToken(token)).toBeNull();
  const all = await svc.listApiTokens(t.actors.admin, t.org.id, t.userIds.member);
  expect(all.every((x) => x.revokedAt !== null)).toBe(true);
  const page = await listActivity(t.actors.admin, { orgId: t.org.id, limit: 100, action: ["api_token.revoked", "api_token.created"] } as never);
  console.log(page.items.map((e) => `${e.action} ${e.actorId === t.userIds.admin ? "admin" : "member"} ${e.subjectKind}`));
  expect(page.items.length).toBe(5 + 1 + 5 - 0);
});
EOF
npx vitest run tests/tmp 2>&1 | tail -40

